def append_to_module(file_path, items, cat_name, planet_name, source_note):
    with open(file_path, "r", encoding="utf-8") as f:
        content = f.read()
    
    # Format the python tuples to append to titles list
    chunk = ""
    for it in items:
        chunk += f'    ("{it[0]}", "{it[1]}", {repr(it[2])}, "{it[3]}", "{it[4]}", {it[5]}, "{it[6]}"),\n'
    
    # We find where titles list begins or ends:
    target = "titles_" + planet_name.lower().replace("सूर्य", "surya").replace("चंद्र", "chandra").replace("मंगल", "mangal").replace("बुध", "budh").replace("गुरु", "guru").replace("शुक्र", "shukra").replace("शनि", "shani").replace("राहु", "rahu").replace("केतु", "ketu") + " = ["
    
    idx = content.find(target)
    if idx != -1:
        insert_pos = idx + len(target) + 1
        new_content = content[:insert_pos] + chunk + content[insert_pos:]
        with open(file_path, "w", encoding="utf-8") as f:
            f.write(new_content)
        print(f"Updated {file_path} with {len(items)} items.")
    else:
        print(f"ERROR: Could not find target in {file_path}")

